use filmcraft_project::{Param,ParamValue};use filmcraft_render::{effects::{apply,FxCtx},image::Image};use serde_json::json;
use filmcraft_render::vfx::FxEnv;use filmcraft_project::EffectInstance;use std::sync::Mutex;
struct Env{requests:Mutex<Vec<serde_json::Value>>,fps:f64,width:u32,key:u64,available:bool,moving:bool,now:f64}
impl FxEnv for Env{
fn source_frame(&self,dt:f64,scale:f32)->Option<Image>{self.requests.lock().unwrap().push(json!({"dtBits":dt.to_bits(),"scaleBits":scale.to_bits()}));if self.moving{let t=self.now+dt;if !(0. ..1.).contains(&t){None}else{Some(picture((t*1000000.).round()as u64))}}else if self.available{Some(Image::new(6,4))}else{None}}
fn frame(&self,_:f64,_:&EffectInstance)->Option<Image>{None}fn track(&self,_:usize)->Option<Image>{None}fn layer_to_output(&self)->filmcraft_geom::Affine{filmcraft_geom::Affine::IDENTITY}fn clip_seconds(&self)->f64{1.}fn clip_offset(&self)->f64{0.}fn frame_rate(&self)->f64{self.fps}fn media_timecode(&self)->String{String::new()}fn file_name(&self)->String{String::new()}fn sequence_name(&self)->String{String::new()}fn sequence_size(&self)->(u32,u32){if self.moving{(10,16)}else{(6,4)}}fn source_size(&self)->(u32,u32){(self.width,if self.moving{10}else{4})}fn clip_key(&self)->u64{self.key}
}
fn rgba(t:u64)->Vec<u8>{(0..180usize).flat_map(|i|{let x=(t/100000%12)as usize+2;if(i%18).abs_diff(x)<=1&&(i/18).abs_diff(4)<=1{[255,192,64,128]}else{[(i*7%32)as u8,(i*3%24)as u8,(i*11%16)as u8,128]}}).collect()}
fn picture(t:u64)->Image{let px=rgba(t).chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;[filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[1]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[2]as f32/255.)*a,a]}).collect();Image{w:18,h:10,px}}
fn main(){let mut cases=vec![];for(w,h)in[(6usize,4usize),(18,10),(7,1),(1,7)]{for scale in [1f32,0.5]{for aspect in 0..5{for zoom in [100f64,175.,400.]{for offset in [[0f64,0.],[1.123456789012,-0.75]]{
 let rgba:Vec<u8>=(0..w*h).flat_map(|i|[(i*17%256)as u8,(i*31%256)as u8,(i*7%256)as u8,128]).collect();let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;[filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[1]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[2]as f32/255.)*a,a]}).collect();let mut img=Image{w,h,px};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="auto_reframe").unwrap().instance();e.params.insert("aspect".into(),Param::new(ParamValue::Choice(aspect)));e.params.insert("zoom".into(),Param::new(ParamValue::Float(zoom)));e.params.insert("offset".into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(offset[0],offset[1]))));let cx=FxCtx{t:filmcraft_time::Tick::ZERO,px_scale:scale,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut img,&e,&cx);cases.push(json!({"width":w,"height":h,"scale":scale,"rgba":rgba,"parameters":{"aspect":aspect,"zoom":zoom,"offset":offset},"bits":img.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
}}}}}let mut temporal=vec![];for preset in 0..3{for fps in [1f64,24.,29.97,60.]{for seconds in [0f64,0.5,1.]{for width in [6u32,640]{for available in [false,true]{let env=Env{requests:Mutex::new(vec![]),fps,width,key:temporal.len()as u64+7000000,available,moving:false,now:seconds};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="auto_reframe").unwrap().instance();e.params.insert("preset".into(),Param::new(ParamValue::Choice(preset)));let mut img=Image::new(6,4);let cx=FxCtx{t:filmcraft_time::Tick::ZERO,px_scale:1.,seconds,timecode:"",clip_name:"",project:None,env:Some(&env),working:filmcraft_color::WorkingSpace::Rec709};apply(&mut img,&e,&cx);temporal.push(json!({"preset":preset,"fps":fps,"seconds":seconds,"width":width,"available":available,"requests":*env.requests.lock().unwrap()}));}}}}}let mut moving=vec![];for preset in 0..3{for aspect in 0..5{for tick in [0u64,250000,500000,900000]{let seconds=tick as f64/1000000.;let env=Env{requests:Mutex::new(vec![]),fps:29.97,width:18,key:moving.len()as u64+8000000,available:true,moving:true,now:seconds};let mut img=picture(tick);let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="auto_reframe").unwrap().instance();e.params.insert("preset".into(),Param::new(ParamValue::Choice(preset)));e.params.insert("aspect".into(),Param::new(ParamValue::Choice(aspect)));e.params.insert("zoom".into(),Param::new(ParamValue::Float(175.)));e.params.insert("offset".into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(1.123456789012,-0.75))));let cx=FxCtx{t:filmcraft_time::Tick::ZERO,px_scale:1.,seconds,timecode:"",clip_name:"",project:None,env:Some(&env),working:filmcraft_color::WorkingSpace::Rec709};apply(&mut img,&e,&cx);moving.push(json!({"tick":tick,"parameters":{"preset":preset,"aspect":aspect,"zoom":175.,"offset":[1.123456789012,-0.75]},"bits":img.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));}}}let mut decimation=vec![];for width in [1u32,159,160,319,320,641,2561,3840]{for height in [1u32,7]{let scale=(160./width as f32).min(1.);let target=width as f32*scale;let mut n=1usize;while n<16&&width as f32/(n as f32*2.)>=target.max(1.){n*=2;}let rgba:Vec<u8>=(0..width as usize*height as usize).flat_map(|i|[(i*17%256)as u8,(i*31%256)as u8,(i*7%256)as u8,[128,255,0,64][i%4]]).collect();let frame=filmcraft_frame::VideoFrame::rgba8(width,height,rgba.clone());let(w,h,px)=frame.to_linear_f32_decimated(n);decimation.push(json!({"width":width,"height":height,"scale":scale,"n":n,"rgba":rgba,"outputWidth":w,"outputHeight":h,"bits":px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));}}println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"temporal":temporal,"moving":moving,"decimation":decimation}));}
